column2:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const path = 'corpus/projects/f32-dsp/';
const source = readFileSync(path + 'main.typed', 'utf8').split('\n');
const { focus } = JSON.parse(readFileSync(path + 'project.json', 'utf8'));
assert.match(source[focus - 1], /const tr: f32/);
console.log('Butterfly focus verified on line', focus);
for (const file of ['main.typed', 'scripts/compare.js', 'project.json', 'notes.md']) {
  const width = Math.max(...readFileSync(path + file, 'utf8').split('\n').map(line => line.length));
  assert.ok(width <= (/\.(json|md)$/.test(file) ? 73 : 80), file);
  console.log(file, width);
}
EOF
git diff --check; git diff -- corpus/projects/f32-dsp/{main.typed,notes.md,scripts/compare.js}
